INSERT INTO `mst_terms_condition` (`terms_con_id`, `principal_id`, `terms_con_category`, `terms_con_title`, `terms_con_content`, `terms_con_status`) VALUES
(1, 1, 1, 'Payment', '<p>Testing Content</p>\r\n', 0),
(2, 2, 1, 'Payment', '<p>75% Payment as Advance along with Order and Balance 25% before despatched of the materials should be in front of DD Favoring BENZEAR INDUSTRIAL ENTERPRISES payable at Coimbatore OR by <br>RTGS. BANK : INDIAN BANK,ACCOUNT NO.: 6176803403, IFS Code : IDIB000C062, Branch : Chinniampalayam Coimbatore.</p>\r\n', 1),
(3, 2, 2, 'Customer Scope', '<p>All Fitings, Electricals, Pneumatic / Smoke, Wall Paint, Flooring should be completed by customer before our Engineer visits for Installation. For Overhead Aluminium system installation we request the customer to arrange the steel support structure above 11 feet from the floor level. Also arrange for Electrician and Plumber during installation.</p>\r\n', 1),
(4, 2, 4, 'Delivery Terms', '<p>Ex. Our Works Vellanaipatty, Coimbatore.</p>\r\n', 1),
(5, 2, 3, 'Delivery Period', '<p>Ex-Stock or 4 weeks from receipt of your confirmed order and 100% payment.</p>\r\n', 1),
(6, 2, 8, 'Transportation', '<p>TO PAY basis only, Our risk and responsibility ceases on the delivering of Goods at your Premises. No claim for breakage or shortage during transit wil be entertain.&nbsp;</p>\r\n', 1),
(7, 2, 5, 'Installation', '<p>The Payment for the same should be sent along with your Order in Advance and inform us 3 Days prior to the actual installation required date. The above charges is for one time visit of our Engineer and any postponement or delay for your site will cost extra. Also arrange for Electrician and Plumber during installation.</p>\r\n', 1),
(8, 2, 7, 'Validity', '<p>This Quotation is valid for 30 days only from date.&nbsp;</p>\r\n', 1),
(9, 3, 1, 'Payment', '<p>100% as Payment in Advance along with Order. Payment should be in front of DD Favoring BENZEAR INDUSTRIAL ENTERPRISES payable at Coimbatore OR by <br>RTGS. BANK : INDIAN BANK,ACCOUNT NO.: 6176803403, IFS Code : IDIB000C062, Branch : Chinniampalayam Coimbatore.</p>\r\n', 1),
(10, 3, 2, 'Customer Scope', '<p>20 Liters of Hydraulic Oil Grade -68 to be arranged by the Customer, All Filltings, Electicals, Pneumatic&nbsp; / Smoke, Wall Paint, Flooring should be completed by customer before our Engineer visits for Installation.</p>\r\n', 1),
(11, 3, 4, 'Delivery Terms', '<p>Ex. Our Works Vellanaipatty, Coimbatore.</p>\r\n', 1),
(12, 3, 3, 'Delivery Period', '<p>Ex-Stock or 4 weeks from receipt of your confirmed order and 100% payment.</p>\r\n', 1),
(13, 3, 8, 'Transportation', '<p>TO PAY basis only, Our risk and responsibility ceases on the delivering of Goods at your Premises. No claim for breakage or shortage during transit wil be entertain.&nbsp;</p>\r\n', 1),
(14, 3, 5, 'Installation', '<p>The Payment for the same should be sent along with your Order in Advance and inform us 3 Days prior to the actual installation required date. The above charges is for one time visit of our Engineer and any postponement or delay for your site will cost extra. Also arrange for Electrician and Plumber during installation.</p>\r\n', 1),
(15, 3, 7, 'Validity', '<p><span style=\"color: rgb(68, 68, 68); font-family: &quot;Open Sans&quot;, sans-serif; font-size: 13px; background-color: rgb(252, 252, 252);\">This Quotation is valid for 30 days only from date</span></p>\r\n', 1),
(16, 2, 1, 'Payment 1', '<p>100% Payment as Advance along with Order&nbsp; in form&nbsp;of DD Favoring BENZEAR INDUSTRIAL ENTERPRISES payable at Coimbatore OR by <br> RTGS. BANK : INDIAN BANK,ACCOUNT NO.: 6176803403, IFS Code : IDIB000C062, Branch : Chinniampalayam Coimbatore.</p>\r\n', 1),
(17, 5, 1, 'Payment', '<p><span style=\"color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px; background-color: rgb(255, 255, 255);\">100% after despatch&nbsp;of the materials&nbsp;in form&nbsp;of DD Favoring BENZEAR INDUSTRIAL ENTERPRISES payable at Coimbatore OR by <br> RTGS. BANK : INDIAN BANK,ACCOUNT NO.: 6176803403, IFS Code : IDIB000C062, Branch : Chinniampalayam Coimbatore.</span></p>\r\n', 1),
(18, 5, 8, 'Transportation', '<p>Paid Basis. ( Inculsive)</p>\r\n', 1),
(19, 5, 3, 'Delivery Period', '<p><span background-color:=\"\" font-size:=\"\" style=\"color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, \" trebuchet=\"\">Ex-Stock or 4 weeks from receipt of your confirmed order.</span></p>\r\n', 1);
